oxy_webhelp_navlinks = {"configure_oracle_workloads-d39307e38449":{"topics":[{"title":"Data transfer mechanisms for Oracle databases","shortdesc":"<p class=\"shortdesc\">The Rubrik cluster uses NFS as the default data transfer mechanism for Oracle         databases. You can enable secure thrift for encrypted, authenticated data         transfer.<\/p>","href":"oracle\/data_transfer_mechanisms_oracle.html","attributes":{"data-id":"data_transfer_mechanisms_oracle"},"menu":{"hasChildren":false},"tocID":"data_transfer_mechanisms_oracle-d39307e38460","next":"data_transfer_mechanisms_oracle-d39307e38460"},{"title":"Configuring sensitive data authentication for Oracle hosts","shortdesc":"<p class=\"shortdesc\">Configure an Oracle host to authenticate to an Oracle database with an authenticated         RBS user account to perform <span class=\"ph\">Data Discovery and Classification<\/span>.<\/p>","href":"oracle\/configuring_sens_data_auth_host.html","attributes":{"data-id":"configuring_sens_data_auth_host"},"menu":{"hasChildren":false},"tocID":"configuring_sens_data_auth_host-d39307e38504","topics":[]},{"title":"Oracle discovery user account","shortdesc":"<p class=\"shortdesc\">An Oracle discovery user account has privileges to query Oracle databases, as an         alternative to using a SYSDBA account.<\/p>","href":"oracle\/oracle_query_user_account.html","attributes":{"data-id":"oracle_query_user_account"},"menu":{"hasChildren":false},"tocID":"oracle_query_user_account-d39307e38518","next":"oracle_query_user_account-d39307e38518"},{"title":"Oracle SEPS wallet","shortdesc":"<p class=\"shortdesc\">The Oracle Secure External Password Store wallet stores database connection         credentials in a client-side wallet, preventing credentials from being exposed on the         command line during database discovery and backup operations.<\/p>","href":"oracle\/oracle_seps_wallet.html","attributes":{"data-id":"oracle_seps_wallet"},"menu":{"hasChildren":false},"tocID":"oracle_seps_wallet-d39307e38573","next":"oracle_seps_wallet-d39307e38573"},{"title":"Oracle TDE databases","shortdesc":"<p class=\"shortdesc\">Rubrik clusters support backups for Oracle databases that use Transparent Data         Encryption to secure data at rest.<\/p>","href":"oracle\/oracle_tde_databases.html","attributes":{"data-id":"oracle_tde_databases"},"menu":{"hasChildren":false},"tocID":"oracle_tde_databases-d39307e38606","next":"oracle_tde_databases-d39307e38606"}]}};